// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): AP English Literature and Composition,
// Unit 1, Short Fiction I. Our own wording and questions, written to the public outline of the AP English Literature and
// Composition Course and Exam Description: its Big Ideas as they apply to the first unit, Setting (SET), Character (CHR),
// Structure (STR), Narration (NAR), Figurative Language (FIG) and Literary Argumentation (LAN). The outline entries below
// are named by those Big Idea abbreviations; the course's numbered topics and skill codes are not cited because they were
// not checked against the current document. One skill per Big Idea. Every passage is either public domain (a sentence or
// two from a story published before 1930, named with author, title and date, and checked against the lines as printed), or
// labelled "Fictional passage" and written for this unit; nothing is quoted from a copyrighted text, and none of English 9's
// or English 10's passages is reused. Facts about the stories are stated plainly and hedged. Every question offers lettered
// choices in its prompt and takes the letter (or the choice's own words); the right letter moves around.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Video pictures: figure coordinates use a 100 x 34 sketch, north/up. Flow arrows trace before labels appear. */
const sketch=(title,regions,notes=[])=>{const pts={},polys=[];regions.forEach(([label,xy,col=0],i)=>{const v=xy.map(([x,y],k)=>{const n=String.fromCharCode(65+k)+i;pts[n]=[x,y];return n;}).join('');polys.push({v,label,col});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes:notes.map(([x,y,text])=>({at:[x,y],text})),dots:'',hide:Object.keys(pts).join('')};};
const flow=(title,stages)=>{const q=sketch(title,stages.map(([label],i)=>[label,[[i*36,13],[i*36+28,13],[i*36+28,25],[i*36,25]],i]),stages.map(([,detail],i)=>[i*36+14,7,detail]));q.segs=[];for(let i=0;i<2;i++){q.pts['P'+i]=[i*36+29,19];q.pts['Q'+i]=[i*36+35,19];q.segs.push({v:`P${i}Q${i}`,arrows:1,col:i,w:2});}q.hide=Object.keys(q.pts).join('');return q;};
const board=(title,lines,why)=>({t:'board',title,lines,...(why?{why}:{})});
const pass=(title,texts,small=true)=>({t:'passages',title,texts,...(small?{small:true}:{})});
const L='ABCDEF';
/* lettered choices, the right one moved to position k: returns {text, letter} */
const dot=o=>o.replace(/\.$/,'');
const choose=(right,wrong,k)=>{right=dot(right);const opts=wrong.map(dot);opts.splice(k%(wrong.length+1),0,right);return {text:opts.map((o,i)=>`${L[i]}: ${o}`).join(', '),letter:L[opts.indexOf(right)],n:opts.length};};
const ask=n=>n===2?'Answer A or B.':n===3?'Answer A, B or C.':`Answer ${[...L.slice(0,n-1)].join(', ')} or ${L[n-1]}.`;
const FIC='Fictional passage';
/* the passages: [source label, lines] */
